insert into products (id, slug, name, category, grade, summary, description, image, gallery, origin, specs, packaging, moq, featured, published, sort_order, translations, is_sample, seo_title, seo_description, created_at, updated_at) values ('b22eb886-73af-4165-8a16-9b6f0c5c934b', 'robusta-s18-clean', 'Robusta S18 Clean', 'coffee', 'G1 · Screen 18 · Polished', 'Large, uniform Robusta beans from the Central Highlands — our benchmark grade for espresso blends.', 'Grown on the red basalt soils of Dak Lak and Gia Lai, sun-dried as whole cherries, then hulled, polished and sorted to Screen 18. The polish removes the silver skin for an even roast; in the cup expect heavy body, low acidity and dark-chocolate depth.', '/photos/grade-robusta-s18.jpg', '["/photos/green-beans-palm.jpg","/photos/factory-sacks-silos.jpg"]', 'Dak Lak / Gia Lai, Central Highlands', '[{"label":"Moisture","value":"12.5% max"},{"label":"Foreign matter","value":"0.1% max"},{"label":"Black & broken","value":"0.1–0.5%"},{"label":"Bean size","value":"90% above Screen 18 (7.1 mm)"},{"label":"Processing","value":"Natural (dry), polished"},{"label":"Grade","value":"G1 · Screen 18 Clean"}]', '60 kg jute bags, PP bags, 1 MT jumbo bags or bulk', '1 × 20ft container (19.2 MT)', 1, 1, 10, '{"ar":{"moq":"حاوية 20 قدم واحدة (19.2 طن)","name":"روبوستا S18 نظيفة","grade":"G1 · غربال 18 · ملمّعة","specs":[{"label":"الرطوبة","value":"12.5% كحد أقصى"},{"label":"المواد الغريبة","value":"0.1% كحد أقصى"},{"label":"الحبوب السوداء والمكسورة","value":"0.1–0.5%"},{"label":"حجم الحبة","value":"90% فوق غربال 18 (7.1 مم)"},{"label":"المعالجة","value":"طبيعية (جافة) مع التلميع"},{"label":"الدرجة","value":"G1 · غربال 18 نظيفة"}],"origin":"داك لاك / جيا لاي، المرتفعات الوسطى","summary":"حبوب روبوستا كبيرة ومتجانسة من المرتفعات الوسطى — درجتنا المرجعية لخلطات الإسبريسو.","packaging":"أكياس جوت 60 كغ، أكياس PP، أكياس جامبو 1 طن أو شحنة سائبة","description":"تُزرع في التربة البازلتية الحمراء في داك لاك وجيا لاي، وتُجفَّف كثمار كاملة ثم تُقشَّر وتُلمَّع وتُفرَز على غربال 18. يزيل التلميع القشرة الفضية لتحميص متجانس، وفي الفنجان قوام كثيف وحموضة منخفضة وعمق الشوكولاتة الداكنة."},"ru":{"moq":"1 × 20ft контейнер (19,2 т)","name":"Робуста S18, очищенная","grade":"G1 · скрин 18 · полировка","specs":[{"label":"Влажность","value":"не более 12,5%"},{"label":"Посторонние примеси","value":"не более 0,1%"},{"label":"Чёрные и битые зёрна","value":"0,1–0,5%"},{"label":"Размер зерна","value":"90% выше скрина 18 (7,1 мм)"},{"label":"Обработка","value":"Натуральная (сухая), с полировкой"},{"label":"Сорт","value":"G1 · скрин 18, очищенная"}],"origin":"Даклак / Зялай, Центральное нагорье","summary":"Крупная однородная робуста из Центрального нагорья — наш эталонный сорт для эспрессо-бленд.","packaging":"Джутовые мешки по 60 кг, мешки PP, биг-бэги 1 т или навалом","description":"Выращена на красных базальтовых почвах Даклака и Зялая, высушена в ягоде, затем очищена, отполирована и откалибрована по скрину 18. Полировка удаляет серебристую плёнку для равномерной обжарки; в чашке — плотное тело, низкая кислотность и глубина тёмного шоколада."}}', 1, '', '', '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.394Z');
insert into products (id, slug, name, category, grade, summary, description, image, gallery, origin, specs, packaging, moq, featured, published, sort_order, translations, is_sample, seo_title, seo_description, created_at, updated_at) values ('53f0f2be-86a9-4fac-a153-6aade659c0fe', 'robusta-s16-clean', 'Robusta S16 Clean', 'coffee', 'G1 · Screen 16', 'A clean Screen 16 Robusta that balances cup quality and price for everyday blends.', 'Natural-processed Robusta from Dak Lak, hulled and machine-sorted to Screen 16 with tight limits on black and broken beans. A dependable choice for roasters who need consistent body in commercial espresso and filter blends.', '/photos/grade-robusta-s16.jpg', '["/photos/green-beans-basket.jpg","/photos/pallet-stack.jpg"]', 'Dak Lak, Central Highlands', '[{"label":"Moisture","value":"12.5% max"},{"label":"Foreign matter","value":"0.1% max"},{"label":"Black & broken","value":"0.1–0.5%"},{"label":"Bean size","value":"90% above Screen 16 (6.3 mm)"},{"label":"Processing","value":"Natural (dry)"},{"label":"Grade","value":"G1 · Screen 16 Clean"}]', '60 kg jute bags, PP bags, 1 MT jumbo bags or bulk', '1 × 20ft container (19.2 MT)', 0, 1, 20, '{"ar":{"moq":"حاوية 20 قدم واحدة (19.2 طن)","name":"روبوستا S16 نظيفة","grade":"G1 · غربال 16","specs":[{"label":"الرطوبة","value":"12.5% كحد أقصى"},{"label":"المواد الغريبة","value":"0.1% كحد أقصى"},{"label":"الحبوب السوداء والمكسورة","value":"0.1–0.5%"},{"label":"حجم الحبة","value":"90% فوق غربال 16 (6.3 مم)"},{"label":"المعالجة","value":"طبيعية (جافة)"},{"label":"الدرجة","value":"G1 · غربال 16 نظيفة"}],"origin":"داك لاك، المرتفعات الوسطى","summary":"روبوستا نظيفة بغربال 16 توازن بين جودة الفنجان والسعر للخلطات اليومية.","packaging":"أكياس جوت 60 كغ، أكياس PP، أكياس جامبو 1 طن أو شحنة سائبة","description":"روبوستا معالجة بالطريقة الطبيعية من داك لاك، مقشّرة ومفروزة آليًا على غربال 16 مع ضبط صارم للحبوب السوداء والمكسورة. خيار موثوق للمحامص التي تحتاج قوامًا ثابتًا في خلطات الإسبريسو والفلتر التجارية."},"ru":{"moq":"1 × 20ft контейнер (19,2 т)","name":"Робуста S16, очищенная","grade":"G1 · скрин 16","specs":[{"label":"Влажность","value":"не более 12,5%"},{"label":"Посторонние примеси","value":"не более 0,1%"},{"label":"Чёрные и битые зёрна","value":"0,1–0,5%"},{"label":"Размер зерна","value":"90% выше скрина 16 (6,3 мм)"},{"label":"Обработка","value":"Натуральная (сухая)"},{"label":"Сорт","value":"G1 · скрин 16, очищенная"}],"origin":"Даклак, Центральное нагорье","summary":"Очищенная робуста скрин 16 — баланс качества чашки и цены для повседневных бленд.","packaging":"Джутовые мешки по 60 кг, мешки PP, биг-бэги 1 т или навалом","description":"Робуста натуральной обработки из Даклака, очищенная и откалиброванная по скрину 16 со строгим контролем чёрных и битых зёрен. Надёжный выбор для обжарщиков, которым нужна стабильная плотность в коммерческих эспрессо- и фильтр-блендах."}}', 1, '', '', '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.394Z');
insert into products (id, slug, name, category, grade, summary, description, image, gallery, origin, specs, packaging, moq, featured, published, sort_order, translations, is_sample, seo_title, seo_description, created_at, updated_at) values ('20904527-2d8c-4a91-8769-5d34e7eed98d', 'robusta-g2-s13-14', 'Robusta S13/S14', 'coffee', 'Screen 13–14 · Clean', 'Clean Robusta in Screen 13–14 for blends and soluble coffee at scale.', 'Natural-processed Robusta from Dak Lak and Gia Lai, cleaned to the same tolerances as our larger grades — 0.1% foreign matter, 0.1–0.5% black and broken — and sorted to Screen 13–14. Suited to volume roasting, blends and soluble programs where price and steady supply lead.', '/photos/grade-robusta-s13.jpg', '["/photos/green-beans-hand.jpg","/photos/warehouse-stacking.jpg"]', 'Dak Lak / Gia Lai, Central Highlands', '[{"label":"Moisture","value":"12.5% max"},{"label":"Foreign matter","value":"0.1% max"},{"label":"Black & broken","value":"0.1–0.5%"},{"label":"Bean size","value":"90% above Screen 13 (5.0 mm)"},{"label":"Processing","value":"Natural (dry)"},{"label":"Grade","value":"S13/S14 Clean"}]', '60 kg jute bags, PP bags, 1 MT jumbo bags or bulk', '1 × 20ft container (19.2 MT bagged, 21.6 MT in bulk)', 0, 1, 30, '{"ar":{"moq":"حاوية 20 قدم واحدة (19.2 طن في أكياس، 21.6 طن سائبة)","name":"روبوستا S13/S14","grade":"غربال 13–14 · نظيفة","specs":[{"label":"الرطوبة","value":"12.5% كحد أقصى"},{"label":"المواد الغريبة","value":"0.1% كحد أقصى"},{"label":"الحبوب السوداء والمكسورة","value":"0.1–0.5%"},{"label":"حجم الحبة","value":"90% فوق غربال 13 (5.0 مم)"},{"label":"المعالجة","value":"طبيعية (جافة)"},{"label":"الدرجة","value":"S13/S14 نظيفة"}],"origin":"داك لاك / جيا لاي، المرتفعات الوسطى","summary":"روبوستا نظيفة بغربال 13–14 للخلطات والقهوة سريعة التحضير بكميات كبيرة.","packaging":"أكياس جوت 60 كغ، أكياس PP، أكياس جامبو 1 طن أو شحنة سائبة","description":"روبوستا معالجة بالطريقة الطبيعية من داك لاك وجيا لاي، منظّفة وفق الحدود نفسها لدرجاتنا الأكبر — 0.1% مواد غريبة و0.1–0.5% حبوب سوداء ومكسورة — ومفروزة على غربال 13–14. مناسبة للتحميص بكميات كبيرة والخلطات والقهوة سريعة التحضير حيث السعر والإمداد المنتظم هما الأولوية."},"ru":{"moq":"1 × 20ft контейнер (19,2 т в мешках, 21,6 т навалом)","name":"Робуста S13/S14","grade":"скрин 13–14 · очищенная","specs":[{"label":"Влажность","value":"не более 12,5%"},{"label":"Посторонние примеси","value":"не более 0,1%"},{"label":"Чёрные и битые зёрна","value":"0,1–0,5%"},{"label":"Размер зерна","value":"90% выше скрина 13 (5,0 мм)"},{"label":"Обработка","value":"Натуральная (сухая)"},{"label":"Сорт","value":"S13/S14, очищенная"}],"origin":"Даклак / Зялай, Центральное нагорье","summary":"Очищенная робуста скрин 13–14 для бленд и растворимого кофе в больших объёмах.","packaging":"Джутовые мешки по 60 кг, мешки PP, биг-бэги 1 т или навалом","description":"Робуста натуральной обработки из Даклака и Зялая, очищенная до тех же допусков, что и наши крупные сорта, — 0,1% посторонних примесей, 0,1–0,5% чёрных и битых зёрен — и откалиброванная по скрину 13–14. Подходит для объёмной обжарки, бленд и растворимого кофе, где важны цена и стабильные поставки."}}', 1, '', '', '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.394Z');
insert into products (id, slug, name, category, grade, summary, description, image, gallery, origin, specs, packaging, moq, featured, published, sort_order, translations, is_sample, seo_title, seo_description, created_at, updated_at) values ('d8acea17-d841-4b84-bb71-b1a864dffb81', 'arabica-s18-clean', 'Arabica S18 Clean', 'coffee', 'G1 · Screen 18 · Washed', 'Fully washed high-altitude Arabica from Cau Dat with bright acidity and a sweet, clean finish.', 'Selectively picked on the cool slopes around Da Lat, pulped, fermented and fully washed before drying. Screen 18 beans with minimal defects suit single-origin programs and specialty blends that want citrus and honey notes.', '/photos/grade-arabica-s18.jpg', '["/photos/green-beans-gloves.jpg","/photos/drying-beds.jpg"]', 'Cau Dat, Lam Dong', '[{"label":"Moisture","value":"12.5% max"},{"label":"Foreign matter","value":"0.1% max"},{"label":"Black & broken","value":"0.1% max"},{"label":"Bean size","value":"90% above Screen 18"},{"label":"Processing","value":"Fully washed"},{"label":"Grade","value":"G1 · Premium"}]', '60 kg jute bags, PP bags, 1 MT jumbo bags or bulk', '1 × 20ft container (19.2 MT)', 1, 1, 40, '{"ar":{"moq":"حاوية 20 قدم واحدة (19.2 طن)","name":"أرابيكا S18 نظيفة","grade":"G1 · غربال 18 · مغسولة","specs":[{"label":"الرطوبة","value":"12.5% كحد أقصى"},{"label":"المواد الغريبة","value":"0.1% كحد أقصى"},{"label":"الحبوب السوداء والمكسورة","value":"0.1% كحد أقصى"},{"label":"حجم الحبة","value":"90% فوق غربال 18"},{"label":"المعالجة","value":"مغسولة بالكامل"},{"label":"الدرجة","value":"G1 · ممتازة"}],"origin":"كاو دات، لام دونغ","summary":"أرابيكا مغسولة بالكامل من مرتفعات كاو دات بحموضة زاهية ونهاية حلوة ونظيفة.","packaging":"أكياس جوت 60 كغ، أكياس PP، أكياس جامبو 1 طن أو شحنة سائبة","description":"تُقطف بانتقاء على المنحدرات الباردة حول دا لات، وتُنزع لبّها وتُخمَّر وتُغسل بالكامل قبل التجفيف. حبوب غربال 18 بأقل قدر من العيوب تناسب برامج القهوة أحادية المصدر والخلطات المختصة ذات نكهات الحمضيات والعسل."},"ru":{"moq":"1 × 20ft контейнер (19,2 т)","name":"Арабика S18, очищенная","grade":"G1 · скрин 18 · мытая","specs":[{"label":"Влажность","value":"не более 12,5%"},{"label":"Посторонние примеси","value":"не более 0,1%"},{"label":"Чёрные и битые зёрна","value":"не более 0,1%"},{"label":"Размер зерна","value":"90% выше скрина 18"},{"label":"Обработка","value":"Полностью мытая"},{"label":"Сорт","value":"G1 · премиум"}],"origin":"Каудат, Ламдонг","summary":"Полностью мытая высокогорная арабика из Каудат с яркой кислотностью и сладким чистым послевкусием.","packaging":"Джутовые мешки по 60 кг, мешки PP, биг-бэги 1 т или навалом","description":"Выборочно собрана на прохладных склонах вокруг Далата, депульпирована, ферментирована и полностью промыта перед сушкой. Зерно скрин 18 с минимумом дефектов подходит для моносортовых программ и спешелти-бленд с цитрусовыми и медовыми нотами."}}', 1, '', '', '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.394Z');
insert into products (id, slug, name, category, grade, summary, description, image, gallery, origin, specs, packaging, moq, featured, published, sort_order, translations, is_sample, seo_title, seo_description, created_at, updated_at) values ('61f250f1-8152-4570-b44d-c37b51368a26', 'arabica-s16-clean', 'Arabica S16 Clean', 'coffee', 'G1 · Screen 16 · Washed', 'Clean, washed Arabica in Screen 16 — a versatile base for house blends.', 'Sourced from Son La in the northwest and Lam Dong in the south, fully washed and graded to Screen 16. Balanced sweetness and mild acidity make it an easy upgrade for blends that currently rely on Robusta alone.', '/photos/grade-arabica-s16.jpg', '["/photos/arabica-s16-washed.jpg","/photos/greenhouse-drying.jpg"]', 'Son La / Lam Dong', '[{"label":"Moisture","value":"12.5% max"},{"label":"Foreign matter","value":"0.1% max"},{"label":"Black & broken","value":"0.1% max"},{"label":"Bean size","value":"90% above Screen 16"},{"label":"Processing","value":"Fully washed"},{"label":"Grade","value":"G1 · Standard clean"}]', '60 kg jute bags, PP bags, 1 MT jumbo bags or bulk', '1 × 20ft container (19.2 MT)', 0, 1, 50, '{"ar":{"moq":"حاوية 20 قدم واحدة (19.2 طن)","name":"أرابيكا S16 نظيفة","grade":"G1 · غربال 16 · مغسولة","specs":[{"label":"الرطوبة","value":"12.5% كحد أقصى"},{"label":"المواد الغريبة","value":"0.1% كحد أقصى"},{"label":"الحبوب السوداء والمكسورة","value":"0.1% كحد أقصى"},{"label":"حجم الحبة","value":"90% فوق غربال 16"},{"label":"المعالجة","value":"مغسولة بالكامل"},{"label":"الدرجة","value":"G1 · قياسية نظيفة"}],"origin":"سون لا / لام دونغ","summary":"أرابيكا مغسولة ونظيفة بغربال 16 — قاعدة متعددة الاستخدامات للخلطات الخاصة.","packaging":"أكياس جوت 60 كغ، أكياس PP، أكياس جامبو 1 طن أو شحنة سائبة","description":"تُورَّد من سون لا في الشمال الغربي ولام دونغ في الجنوب، مغسولة بالكامل ومصنّفة على غربال 16. حلاوتها المتوازنة وحموضتها المعتدلة تجعلها ترقية سهلة للخلطات المعتمدة على الروبوستا وحدها."},"ru":{"moq":"1 × 20ft контейнер (19,2 т)","name":"Арабика S16, очищенная","grade":"G1 · скрин 16 · мытая","specs":[{"label":"Влажность","value":"не более 12,5%"},{"label":"Посторонние примеси","value":"не более 0,1%"},{"label":"Чёрные и битые зёрна","value":"не более 0,1%"},{"label":"Размер зерна","value":"90% выше скрина 16"},{"label":"Обработка","value":"Полностью мытая"},{"label":"Сорт","value":"G1 · стандарт, очищенная"}],"origin":"Шонла / Ламдонг","summary":"Чистая мытая арабика скрин 16 — универсальная основа для фирменных бленд.","packaging":"Джутовые мешки по 60 кг, мешки PP, биг-бэги 1 т или навалом","description":"Закупается в Шонла на северо-западе и в Ламдонге на юге, полностью мытая и откалиброванная по скрину 16. Сбалансированная сладость и мягкая кислотность — простой способ улучшить бленды, построенные только на робусте."}}', 1, '', '', '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.394Z');
insert into products (id, slug, name, category, grade, summary, description, image, gallery, origin, specs, packaging, moq, featured, published, sort_order, translations, is_sample, seo_title, seo_description, created_at, updated_at) values ('3520f07d-b6c6-4872-adb1-0240bfc2076d', 'arabica-s13-14', 'Arabica S13/S14', 'coffee', 'G1 · Screen 13–14', 'Value Arabica in Screen 13–14 from northwest Vietnam for blends and ready-to-drink coffee.', 'Washed and semi-washed Arabica from the mountains of the northwest, graded G1 and sorted to Screen 13–14. A cost-effective way to bring Arabica character to blends, cold brew and RTD products.', '/photos/grade-arabica-s13.jpg', '["/photos/green-beans-gloves.jpg","/photos/cherry-sorting.jpg"]', 'Northwest Vietnam', '[{"label":"Moisture","value":"12.5% max"},{"label":"Foreign matter","value":"0.1% max"},{"label":"Black & broken","value":"0.5% max"},{"label":"Bean size","value":"90% above Screen 13/14"},{"label":"Processing","value":"Washed / semi-washed"},{"label":"Grade","value":"G1"}]', '60 kg jute bags, PP bags, 1 MT jumbo bags or bulk', '1 × 20ft container (19.2 MT)', 0, 1, 60, '{"ar":{"moq":"حاوية 20 قدم واحدة (19.2 طن)","name":"أرابيكا S13/S14","grade":"G1 · غربال 13–14","specs":[{"label":"الرطوبة","value":"12.5% كحد أقصى"},{"label":"المواد الغريبة","value":"0.1% كحد أقصى"},{"label":"الحبوب السوداء والمكسورة","value":"0.5% كحد أقصى"},{"label":"حجم الحبة","value":"90% فوق غربال 13/14"},{"label":"المعالجة","value":"مغسولة / شبه مغسولة"},{"label":"الدرجة","value":"G1"}],"origin":"شمال غرب فيتنام","summary":"أرابيكا اقتصادية بغربال 13–14 من شمال غرب فيتنام للخلطات والقهوة الجاهزة للشرب.","packaging":"أكياس جوت 60 كغ، أكياس PP، أكياس جامبو 1 طن أو شحنة سائبة","description":"أرابيكا مغسولة وشبه مغسولة من جبال الشمال الغربي، من الدرجة G1 ومفروزة على غربال 13–14. طريقة اقتصادية لإضافة طابع الأرابيكا إلى الخلطات والقهوة الباردة والمشروبات الجاهزة."},"ru":{"moq":"1 × 20ft контейнер (19,2 т)","name":"Арабика S13/S14","grade":"G1 · скрин 13–14","specs":[{"label":"Влажность","value":"не более 12,5%"},{"label":"Посторонние примеси","value":"не более 0,1%"},{"label":"Чёрные и битые зёрна","value":"не более 0,5%"},{"label":"Размер зерна","value":"90% выше скрина 13/14"},{"label":"Обработка","value":"Мытая / полумытая"},{"label":"Сорт","value":"G1"}],"origin":"Северо-запад Вьетнама","summary":"Доступная арабика скрин 13–14 с северо-запада Вьетнама для бленд и готовых кофейных напитков.","packaging":"Джутовые мешки по 60 кг, мешки PP, биг-бэги 1 т или навалом","description":"Мытая и полумытая арабика из гор северо-запада, сорт G1, откалиброванная по скрину 13–14. Экономичный способ добавить характер арабики в бленды, колд-брю и готовые напитки."}}', 1, '', '', '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.394Z');
insert into products (id, slug, name, category, grade, summary, description, image, gallery, origin, specs, packaging, moq, featured, published, sort_order, translations, is_sample, seo_title, seo_description, created_at, updated_at) values ('49f4fe79-63dd-4aaf-ac66-a260dff2f547', 'roasted-ground-blend-70-30', 'Roasted & Ground Coffee 70/30', 'coffee', '70% Robusta · 30% Arabica', 'A roasted and ground blend of 70% Vietnamese Robusta and 30% Arabica, packed in valve bags for retail, HoReCa and private label.', 'A ready-to-sell blend: Robusta from the Central Highlands gives body and crema, Arabica from Lam Dong adds aroma. Roasted to the profile you agree with us, ground for espresso, filter or phin, and packed in one-way-valve bags — under your own label on request.', '/photos/roasted-beans-bags.jpg', '["/photos/roasting-packing-line.jpg"]', 'Robusta: Central Highlands · Arabica: Lam Dong', '[{"label":"Blend","value":"70% Robusta / 30% Arabica"},{"label":"Form","value":"Roasted & ground (whole bean on request)"},{"label":"Roast level","value":"Agreed per order"},{"label":"Grind","value":"Espresso, filter or phin — to order"}]', 'Bags with one-way degassing valve; private label on request', 'On request', 0, 1, 70, '{"ar":{"moq":"عند الطلب","name":"قهوة محمّصة ومطحونة 70/30","grade":"70% روبوستا · 30% أرابيكا","specs":[{"label":"الخلطة","value":"70% روبوستا / 30% أرابيكا"},{"label":"الشكل","value":"محمّصة ومطحونة (حبوب كاملة عند الطلب)"},{"label":"درجة التحميص","value":"يُتفق عليها في كل طلبية"},{"label":"الطحن","value":"إسبريسو أو فلتر أو فين — حسب الطلب"}],"origin":"روبوستا: المرتفعات الوسطى · أرابيكا: لام دونغ","summary":"خلطة محمّصة ومطحونة من 70% روبوستا فيتنامية و30% أرابيكا، معبأة في أكياس بصمام لتجارة التجزئة والفنادق والمطاعم والعلامات الخاصة.","packaging":"أكياس بصمام أحادي الاتجاه لتصريف الغازات؛ علامة خاصة عند الطلب","description":"خلطة جاهزة للبيع: تمنح روبوستا المرتفعات الوسطى القوام والكريما، وتضيف أرابيكا لام دونغ الرائحة. نحمّصها وفق الدرجة المتفق عليها معكم، ونطحنها للإسبريسو أو الفلتر أو الفين، ونعبّئها في أكياس بصمام أحادي الاتجاه — وتحت علامتكم الخاصة عند الطلب."},"ru":{"moq":"По запросу","name":"Молотый жареный кофе 70/30","grade":"70% робуста · 30% арабика","specs":[{"label":"Бленд","value":"70% робуста / 30% арабика"},{"label":"Форма","value":"Жареный молотый (зерно — по запросу)"},{"label":"Степень обжарки","value":"Согласуется в заказе"},{"label":"Помол","value":"Эспрессо, фильтр или фин — под заказ"}],"origin":"Робуста: Центральное нагорье · Арабика: Ламдонг","summary":"Жареный молотый бленд из 70% вьетнамской робусты и 30% арабики в пакетах с клапаном — для розницы, HoReCa и частной марки.","packaging":"Пакеты с односторонним клапаном дегазации; частная марка по запросу","description":"Готовый к продаже бленд: робуста из Центрального нагорья даёт плотность и крему, арабика из Ламдонга — аромат. Обжариваем по согласованному с вами профилю, мелем для эспрессо, фильтра или фина и фасуем в пакеты с односторонним клапаном — по запросу под вашей маркой."}}', 1, '', '', '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.381Z');
insert into products (id, slug, name, category, grade, summary, description, image, gallery, origin, specs, packaging, moq, featured, published, sort_order, translations, is_sample, seo_title, seo_description, created_at, updated_at) values ('8cfd22c9-7aaa-4718-8216-08d922dffa92', 'robusta-fully-washed-special-g1', 'Robusta Fully Washed Special G1', 'coffee', 'Special G1 · Screen 16 / 18 · Fully washed', 'Fully washed Special Grade 1 Robusta in Screen 16 or 18 — zero black beans and our tightest defect limits.', 'Ripe cherries are pulped, fermented and fully washed before drying, then hulled and sorted to Screen 16 or Screen 18. Washing strips the mucilage that gives natural Robusta its earthy edge, leaving a cleaner, sweeter cup — a Robusta that can stand on its own in specialty espresso and single-origin programs.', 'https://images.unsplash.com/photo-1561766858-62033ae40ec3', '["https://images.unsplash.com/photo-1750967613671-297f1b63038d","https://images.unsplash.com/photo-1524350876685-274059332603"]', 'Central Highlands, Vietnam', '[{"label":"Moisture","value":"12.5% max"},{"label":"Black beans","value":"0%"},{"label":"Broken beans","value":"0.2% max"},{"label":"Foreign matter","value":"0.1% max"},{"label":"Sticks & stones","value":"0.02% max"},{"label":"Bean size","value":"90% above Screen 18 (7.1 mm) or Screen 16 (6.3 mm)"},{"label":"Processing","value":"Fully washed"},{"label":"Grade","value":"Special G1"}]', '60 kg jute bags batched with vegetable oil', '1 × 20ft container (18 MT)', 0, 0, 75, '{"ar":{"moq":"حاوية 20 قدم واحدة (18 طن)","name":"روبوستا مغسولة بالكامل Special G1","grade":"Special G1 · غربال 16 / 18 · مغسولة بالكامل","specs":[{"label":"الرطوبة","value":"12.5% كحد أقصى"},{"label":"الحبوب السوداء","value":"0%"},{"label":"الحبوب المكسورة","value":"0.2% كحد أقصى"},{"label":"المواد الغريبة","value":"0.1% كحد أقصى"},{"label":"العيدان والحجارة","value":"0.02% كحد أقصى"},{"label":"حجم الحبة","value":"90% فوق غربال 18 (7.1 مم) أو غربال 16 (6.3 مم)"},{"label":"المعالجة","value":"مغسولة بالكامل"},{"label":"الدرجة","value":"Special G1"}],"origin":"المرتفعات الوسطى، فيتنام","summary":"روبوستا مغسولة بالكامل من الدرجة الخاصة الأولى بغربال 16 أو 18 — دون حبوب سوداء وبأدق حدود العيوب لدينا.","packaging":"أكياس جوت 60 كغ معالجة بالزيت النباتي","description":"تُزال لبّ الثمار الناضجة وتُخمَّر وتُغسل بالكامل قبل التجفيف، ثم تُقشَّر وتُفرَز على غربال 16 أو 18. يزيل الغسل الطبقة اللزجة التي تمنح الروبوستا الطبيعية طابعها الترابي، فيأتي الفنجان أنظف وأحلى — روبوستا تقف بذاتها في برامج الإسبريسو المختصة وأحادية المصدر."},"ru":{"moq":"1 × 20ft контейнер (18 т)","name":"Робуста полностью мытая, Special G1","grade":"Special G1 · скрин 16 / 18 · полностью мытая","specs":[{"label":"Влажность","value":"не более 12,5%"},{"label":"Чёрные зёрна","value":"0%"},{"label":"Битые зёрна","value":"не более 0,2%"},{"label":"Посторонние примеси","value":"не более 0,1%"},{"label":"Палочки и камни","value":"не более 0,02%"},{"label":"Размер зерна","value":"90% выше скрина 18 (7,1 мм) или скрина 16 (6,3 мм)"},{"label":"Обработка","value":"Полностью мытая"},{"label":"Сорт","value":"Special G1"}],"origin":"Центральное нагорье, Вьетнам","summary":"Полностью мытая робуста Special Grade 1 скрин 16 или 18 — без чёрных зёрен и с самыми строгими допусками по дефектам.","packaging":"Джутовые мешки по 60 кг, обработанные растительным маслом","description":"Спелые ягоды депульпируют, ферментируют и полностью промывают перед сушкой, затем очищают и калибруют по скрину 16 или 18. Промывка удаляет слизистый слой, который придаёт натуральной робусте землистые ноты, — чашка получается чище и слаще. Робуста, способная звучать самостоятельно в спешелти-эспрессо и моносортовых программах."}}', 1, '', '', '2026-10-21T23:01:24.389Z', '2026-10-21T23:01:24.393Z');
insert into products (id, slug, name, category, grade, summary, description, image, gallery, origin, specs, packaging, moq, featured, published, sort_order, translations, is_sample, seo_title, seo_description, created_at, updated_at) values ('3f4eedcf-8cc9-4ae6-9622-2b546a84ce93', 'cashew-ww160', 'Cashew Kernels WW160', 'cashew', 'White Wholes · 160', 'The largest AFI whole — for premium gifting and luxury retail in the Middle East and East Asia.', 'Cashew Kernels WW160 are whole white kernels graded to AFI at 140–160 kernels/lb (309–353/kg). The nuts are steamed, shelled, dried and peeled in Vietnam''s southeastern cashew belt, then sorted by size and colour and vacuum-packed to keep their crunch and sweetness on long ocean voyages.', '/photos/cashew-kernels-closeup.jpg', '["/photos/cashew-vacuum-bags.jpg","/photos/cashew-cartons-open.jpg"]', 'Southeast Vietnam (Binh Phuoc / Dong Nai)', '[{"label":"Count","value":"140–160 kernels/lb (309–353/kg)"},{"label":"Moisture","value":"5% max"},{"label":"Broken","value":"5% max"},{"label":"Colour","value":"White to pale ivory"},{"label":"Standard","value":"AFI specification"},{"label":"Crop","value":"2026"}]', '1 × 22.68 kg vacuum bag or 2 × 11.34 kg tins in 5-ply export cartons', '1 × 20ft container (700–720 cartons, about 16 MT)', 0, 1, 80, '{"ar":{"moq":"حاوية 20 قدم واحدة (700–720 كرتونة، نحو 16 طنًا)","name":"كاجو WW160","grade":"كاجو أبيض كامل · 160","specs":[{"label":"العدد","value":"140–160 حبة/رطل (309–353/كغ)"},{"label":"الرطوبة","value":"5% كحد أقصى"},{"label":"المكسور","value":"5% كحد أقصى"},{"label":"اللون","value":"أبيض إلى عاجي فاتح"},{"label":"المعيار","value":"مواصفات AFI"},{"label":"المحصول","value":"2026"}],"origin":"جنوب شرق فيتنام (بينه فوك / دونغ ناي)","summary":"أكبر درجة كاملة وفق AFI — للهدايا الفاخرة والتجزئة الراقية في الشرق الأوسط وشرق آسيا.","packaging":"كيس مفرّغ 1 × 22.68 كغ أو علبتا صفيح 2 × 11.34 كغ في كرتونة تصدير خماسية الطبقات","description":"كاجو WW160 حبات كاجو بيضاء كاملة مصنّفة وفق AFI بعدد 140–160 حبة/رطل (309–353/كغ). تُبخَّر المكسرات وتُكسر قشرتها وتُجفَّف وتُنزع أغلفتها في حزام الكاجو جنوب شرق فيتنام، ثم تُفرز حسب الحجم واللون وتُعبّأ مفرّغة من الهواء للحفاظ على قرمشتها وحلاوتها خلال الرحلات البحرية الطويلة."},"ru":{"moq":"1 × 20ft контейнер (700–720 коробок, около 16 т)","name":"Ядра кешью WW160","grade":"Белые цельные · 160","specs":[{"label":"Калибр","value":"140–160 ядер/фунт (309–353/кг)"},{"label":"Влажность","value":"не более 5%"},{"label":"Битые ядра","value":"не более 5%"},{"label":"Цвет","value":"Белый — светлая слоновая кость"},{"label":"Стандарт","value":"Спецификация AFI"},{"label":"Урожай","value":"2026"}],"origin":"Юго-восток Вьетнама (Биньфыок / Донгнай)","summary":"Самый крупный цельный калибр по AFI — для премиальных подарков и люкс-ритейла на Ближнем Востоке и в Восточной Азии.","packaging":"Вакуумный пакет 1 × 22,68 кг или жестяные банки 2 × 11,34 кг в пятислойных экспортных коробках","description":"Ядра кешью WW160 — цельные белые ядра калибра 140–160 ядер/фунт (309–353/кг) по стандарту AFI. Орехи пропаривают, раскалывают, сушат и очищают на юго-востоке Вьетнама, затем сортируют по размеру и цвету и упаковывают под вакуумом, чтобы сохранить хруст и сладость в долгом морском рейсе."}}', 1, '', '', '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.400Z');
insert into products (id, slug, name, category, grade, summary, description, image, gallery, origin, specs, packaging, moq, featured, published, sort_order, translations, is_sample, seo_title, seo_description, created_at, updated_at) values ('b06bfa9f-37c2-4e18-b4c3-20bf3f18fd01', 'cashew-ww180', 'Cashew Kernels WW180', 'cashew', 'White Wholes · 180', 'Extra-large whites for premium gift boxes and upscale retail.', 'Cashew Kernels WW180 are whole white kernels graded to AFI at 160–180 kernels/lb (353–397/kg). The nuts are steamed, shelled, dried and peeled in Vietnam''s southeastern cashew belt, then sorted by size and colour and vacuum-packed to keep their crunch and sweetness on long ocean voyages.', '/photos/cashew-kernels-pile.jpg', '["/photos/cashew-cartons-open.jpg","/photos/cashew-container-cartons.jpg"]', 'Southeast Vietnam (Binh Phuoc / Dong Nai)', '[{"label":"Count","value":"160–180 kernels/lb (353–397/kg)"},{"label":"Moisture","value":"5% max"},{"label":"Broken","value":"5% max"},{"label":"Colour","value":"White to pale ivory"},{"label":"Standard","value":"AFI specification"},{"label":"Crop","value":"2026"}]', '1 × 22.68 kg vacuum bag or 2 × 11.34 kg tins in 5-ply export cartons', '1 × 20ft container (700–720 cartons, about 16 MT)', 0, 1, 90, '{"ar":{"moq":"حاوية 20 قدم واحدة (700–720 كرتونة، نحو 16 طنًا)","name":"كاجو WW180","grade":"كاجو أبيض كامل · 180","specs":[{"label":"العدد","value":"160–180 حبة/رطل (353–397/كغ)"},{"label":"الرطوبة","value":"5% كحد أقصى"},{"label":"المكسور","value":"5% كحد أقصى"},{"label":"اللون","value":"أبيض إلى عاجي فاتح"},{"label":"المعيار","value":"مواصفات AFI"},{"label":"المحصول","value":"2026"}],"origin":"جنوب شرق فيتنام (بينه فوك / دونغ ناي)","summary":"حبات بيضاء كبيرة جدًا لعلب الهدايا الفاخرة والتجزئة الراقية.","packaging":"كيس مفرّغ 1 × 22.68 كغ أو علبتا صفيح 2 × 11.34 كغ في كرتونة تصدير خماسية الطبقات","description":"كاجو WW180 حبات كاجو بيضاء كاملة مصنّفة وفق AFI بعدد 160–180 حبة/رطل (353–397/كغ). تُبخَّر المكسرات وتُكسر قشرتها وتُجفَّف وتُنزع أغلفتها في حزام الكاجو جنوب شرق فيتنام، ثم تُفرز حسب الحجم واللون وتُعبّأ مفرّغة من الهواء للحفاظ على قرمشتها وحلاوتها خلال الرحلات البحرية الطويلة."},"ru":{"moq":"1 × 20ft контейнер (700–720 коробок, около 16 т)","name":"Ядра кешью WW180","grade":"Белые цельные · 180","specs":[{"label":"Калибр","value":"160–180 ядер/фунт (353–397/кг)"},{"label":"Влажность","value":"не более 5%"},{"label":"Битые ядра","value":"не более 5%"},{"label":"Цвет","value":"Белый — светлая слоновая кость"},{"label":"Стандарт","value":"Спецификация AFI"},{"label":"Урожай","value":"2026"}],"origin":"Юго-восток Вьетнама (Биньфыок / Донгнай)","summary":"Очень крупные белые ядра для премиальных подарочных наборов и дорогого ритейла.","packaging":"Вакуумный пакет 1 × 22,68 кг или жестяные банки 2 × 11,34 кг в пятислойных экспортных коробках","description":"Ядра кешью WW180 — цельные белые ядра калибра 160–180 ядер/фунт (353–397/кг) по стандарту AFI. Орехи пропаривают, раскалывают, сушат и очищают на юго-востоке Вьетнама, затем сортируют по размеру и цвету и упаковывают под вакуумом, чтобы сохранить хруст и сладость в долгом морском рейсе."}}', 1, '', '', '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.400Z');
