insert into products (id, slug, name, category, grade, summary, description, image, gallery, origin, specs, packaging, moq, featured, published, sort_order, translations, is_sample, seo_title, seo_description, created_at, updated_at) values ('0bda1219-02af-4a60-bf9e-7bd9b6938a41', 'roasted-cashews-with-skin', 'Salt-Roasted Cashews with Skin', 'cashew', 'Roasted · skin on', 'Kernels roasted with the red skin on — deeper flavour and natural polyphenols for clean-label snacking.', 'Whole kernels are slow-roasted with the thin red testa left on, which keeps its natural antioxidants and gives a richer, slightly tannic taste. Lightly salted and packed fresh, they fit the growing demand for natural, minimally processed snacks in Asia, the Middle East and Europe.', 'https://images.unsplash.com/photo-1723466998040-78d7e2ef6d72', '["https://images.unsplash.com/photo-1509912760195-4f6cfd8cce2c","https://images.unsplash.com/photo-1729514256038-c489695f4d79"]', 'Roasted in Vietnam', '[{"label":"Base kernel","value":"W240 or W320"},{"label":"Roasting","value":"Dry roasted (wood-fired or gas)"},{"label":"Moisture","value":"1.0–1.5% after roasting"},{"label":"Salt","value":"0.5–1%"},{"label":"Shelf life","value":"12 months"},{"label":"Private label","value":"Available"}]', 'Vacuum bags, tins or private-label retail pouches (30–500 g)', '1,000 kg', 0, 1, 290, '{"ar":{"moq":"1000 كغ","name":"كاجو محمّص مملّح بالقشرة","grade":"محمّص · بالقشرة","specs":[{"label":"الحبة الأساسية","value":"W240 أو W320"},{"label":"التحميص","value":"تحميص جاف (بالحطب أو الغاز)"},{"label":"الرطوبة","value":"1.0–1.5% بعد التحميص"},{"label":"الملح","value":"0.5–1%"},{"label":"مدة الصلاحية","value":"12 شهرًا"},{"label":"العلامة الخاصة","value":"متاحة"}],"origin":"محمّص في فيتنام","summary":"حبات محمّصة بقشرتها الحمراء — نكهة أعمق وبوليفينولات طبيعية لوجبات خفيفة بمكوّنات نظيفة.","packaging":"أكياس مفرّغة أو علب صفيح أو أكياس تجزئة بعلامة خاصة (30–500 غ)","description":"تُحمَّص الحبات الكاملة ببطء مع إبقاء الغلاف الأحمر الرقيق، ما يحفظ مضادات الأكسدة الطبيعية ويمنح طعمًا أغنى بقليل من القبض. مملّحة قليلًا ومعبّأة طازجة، تلبي الطلب المتزايد على الوجبات الخفيفة الطبيعية قليلة المعالجة في آسيا والشرق الأوسط وأوروبا."},"ru":{"moq":"1 000 кг","name":"Обжаренный кешью в кожуре с солью","grade":"Обжаренный · в кожуре","specs":[{"label":"Базовое ядро","value":"W240 или W320"},{"label":"Обжарка","value":"Сухая обжарка (на дровах или газе)"},{"label":"Влажность","value":"1,0–1,5% после обжарки"},{"label":"Соль","value":"0,5–1%"},{"label":"Срок годности","value":"12 месяцев"},{"label":"СТМ","value":"Доступна"}],"origin":"Обжарено во Вьетнаме","summary":"Ядра, обжаренные в красной кожуре, — насыщенный вкус и природные полифенолы для снеков с чистым составом.","packaging":"Вакуумные пакеты, жестяные банки или розничные пакеты под СТМ (30–500 г)","description":"Цельные ядра медленно обжаривают, оставляя тонкую красную кожуру: она сохраняет природные антиоксиданты и даёт более насыщенный, слегка терпкий вкус. Слегка подсоленный и свежеупакованный продукт отвечает растущему спросу на натуральные снеки минимальной обработки в Азии, на Ближнем Востоке и в Европе."}}', 1, '', '', '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.381Z');
insert into products (id, slug, name, category, grade, summary, description, image, gallery, origin, specs, packaging, moq, featured, published, sort_order, translations, is_sample, seo_title, seo_description, created_at, updated_at) values ('680a781b-f7d4-4a50-b9a4-17f429dd40b8', 'roasted-salted-cashews', 'Roasted Salted Cashews', 'cashew', 'Roasted · peeled', 'The classic peeled, lightly salted roasted cashew — crunchy, even and the world''s best-selling snack nut format.', 'Peeled whole kernels roasted to an even golden colour and seasoned with sea salt to your preferred level. Supplied in bulk for repacking or in finished retail packs under your own brand.', 'https://images.unsplash.com/photo-1509912760195-4f6cfd8cce2c', '["https://images.unsplash.com/photo-1729796350013-ebb27f079c76","https://images.unsplash.com/photo-1723466998040-78d7e2ef6d72"]', 'Roasted in Vietnam', '[{"label":"Base kernel","value":"W240 or W320"},{"label":"Roasting","value":"Dry or oil roasted"},{"label":"Salt","value":"1–2.5% (adjustable)"},{"label":"Moisture","value":"3% max"},{"label":"Shelf life","value":"12 months"},{"label":"Private label","value":"Available"}]', 'Vacuum bags, tins or private-label retail pouches (30–500 g)', '1,000 kg', 0, 1, 300, '{"ar":{"moq":"1000 كغ","name":"كاجو محمّص مملّح","grade":"محمّص · منزوع القشرة","specs":[{"label":"الحبة الأساسية","value":"W240 أو W320"},{"label":"التحميص","value":"تحميص جاف أو بالزيت"},{"label":"الملح","value":"1–2.5% (قابلة للتعديل)"},{"label":"الرطوبة","value":"3% كحد أقصى"},{"label":"مدة الصلاحية","value":"12 شهرًا"},{"label":"العلامة الخاصة","value":"متاحة"}],"origin":"محمّص في فيتنام","summary":"الكاجو المحمّص المملّح الكلاسيكي منزوع القشرة — مقرمش ومتجانس وأكثر أشكال المكسرات الخفيفة مبيعًا في العالم.","packaging":"أكياس مفرّغة أو علب صفيح أو أكياس تجزئة بعلامة خاصة (30–500 غ)","description":"حبات كاملة منزوعة القشرة محمّصة حتى لون ذهبي متجانس ومتبّلة بملح البحر حسب الدرجة التي تفضّلها. تُورَّد بالجملة لإعادة التعبئة أو في عبوات تجزئة جاهزة تحمل علامتك."},"ru":{"moq":"1 000 кг","name":"Обжаренный солёный кешью","grade":"Обжаренный · очищенный","specs":[{"label":"Базовое ядро","value":"W240 или W320"},{"label":"Обжарка","value":"Сухая обжарка или в масле"},{"label":"Соль","value":"1–2,5% (по запросу)"},{"label":"Влажность","value":"не более 3%"},{"label":"Срок годности","value":"12 месяцев"},{"label":"СТМ","value":"Доступна"}],"origin":"Обжарено во Вьетнаме","summary":"Классический очищенный слегка солёный обжаренный кешью — хрустящий, ровный и самый продаваемый формат орехового снека.","packaging":"Вакуумные пакеты, жестяные банки или розничные пакеты под СТМ (30–500 г)","description":"Очищенные цельные ядра, обжаренные до ровного золотистого цвета и приправленные морской солью по вашему вкусу. Поставляются навалом для перефасовки или в готовой розничной упаковке под вашим брендом."}}', 1, '', '', '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.381Z');
insert into products (id, slug, name, category, grade, summary, description, image, gallery, origin, specs, packaging, moq, featured, published, sort_order, translations, is_sample, seo_title, seo_description, created_at, updated_at) values ('a667f827-c61b-4c44-a170-1849719f3cff', 'cappuccino-cashews', 'Cappuccino Cashews', 'cashew', 'Flavoured · cappuccino', 'Cashews coated in creamy cappuccino — a sweet-bitter snack made for coffee lovers.', 'W320 kernels are roasted and tumbled in coffee, milk powder, brown sugar, then cooled and packed to lock in the coating. Available in bulk or in retail pouches with your own label; a natural pairing with Vietnamese coffee gift sets.', 'https://images.unsplash.com/photo-1729796350013-ebb27f079c76', '["https://images.unsplash.com/photo-1509912760195-4f6cfd8cce2c","https://images.unsplash.com/photo-1723466998040-78d7e2ef6d72"]', 'Roasted in Vietnam', '[{"label":"Base kernel","value":"W320"},{"label":"Seasoning","value":"Coffee, milk powder, brown sugar"},{"label":"Taste","value":"Creamy coffee, lightly sweet"},{"label":"Shelf life","value":"12 months"},{"label":"Private label","value":"Available"}]', 'Vacuum bags, tins or private-label retail pouches (30–500 g)', '1,000 kg per flavour', 0, 1, 310, '{"ar":{"moq":"1000 كغ لكل نكهة","name":"كاجو بنكهة الكابتشينو","grade":"منكّه · كابتشينو","specs":[{"label":"الحبة الأساسية","value":"W320"},{"label":"التتبيلة","value":"قهوة، حليب مجفف، سكر بني"},{"label":"المذاق","value":"قهوة كريمية بحلاوة خفيفة"},{"label":"مدة الصلاحية","value":"12 شهرًا"},{"label":"العلامة الخاصة","value":"متاحة"}],"origin":"محمّص في فيتنام","summary":"كاجو مغلّف بالكابتشينو الكريمي — وجبة خفيفة حلوة ومرّة لعشاق القهوة.","packaging":"أكياس مفرّغة أو علب صفيح أو أكياس تجزئة بعلامة خاصة (30–500 غ)","description":"تُحمَّص حبات W320 وتُقلَّب في تتبيلة (قهوة، حليب مجفف، سكر بني)، ثم تُبرَّد وتُعبّأ للحفاظ على الطبقة. متوفرة بالجملة أو في أكياس تجزئة بعلامتك الخاصة؛ وهي رفيق طبيعي لهدايا القهوة الفيتنامية."},"ru":{"moq":"1 000 кг на вкус","name":"Кешью «Капучино»","grade":"С приправой · капучино","specs":[{"label":"Базовое ядро","value":"W320"},{"label":"Приправа","value":"Кофе, сухое молоко, коричневый сахар"},{"label":"Вкус","value":"Сливочный кофе, слегка сладкий"},{"label":"Срок годности","value":"12 месяцев"},{"label":"СТМ","value":"Доступна"}],"origin":"Обжарено во Вьетнаме","summary":"Кешью в сливочной глазури капучино — сладко-горький снек для любителей кофе.","packaging":"Вакуумные пакеты, жестяные банки или розничные пакеты под СТМ (30–500 г)","description":"Ядра W320 обжаривают и обваливают в приправе (кофе, сухое молоко, коричневый сахар), затем охлаждают и упаковывают, сохраняя покрытие. Поставляется навалом или в розничных пакетах под вашей маркой; естественное дополнение к подаркам с вьетнамским кофе."}}', 1, '', '', '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.381Z');
insert into products (id, slug, name, category, grade, summary, description, image, gallery, origin, specs, packaging, moq, featured, published, sort_order, translations, is_sample, seo_title, seo_description, created_at, updated_at) values ('6573763f-0b15-47a7-8fcf-f55ab141682f', 'chili-lime-cashews', 'Chili Lime Cashews', 'cashew', 'Flavoured · chili-lime', 'A Southeast Asian classic: chili heat and fragrant lime leaf on crunchy roasted cashews.', 'W320 kernels are roasted and tumbled in chili, kaffir lime leaf, sea salt, then cooled and packed to lock in the coating. Available in bulk or in retail pouches with your own label; shredded lime leaves are roasted with the nuts for a fresh aroma.', 'https://images.unsplash.com/photo-1509912760195-4f6cfd8cce2c', '["https://images.unsplash.com/photo-1729796350013-ebb27f079c76","https://images.unsplash.com/photo-1723466998040-78d7e2ef6d72"]', 'Roasted in Vietnam', '[{"label":"Base kernel","value":"W320"},{"label":"Seasoning","value":"Chili, kaffir lime leaf, sea salt"},{"label":"Taste","value":"Spicy, salty, fresh lime"},{"label":"Shelf life","value":"12 months"},{"label":"Private label","value":"Available"}]', 'Vacuum bags, tins or private-label retail pouches (30–500 g)', '1,000 kg per flavour', 0, 1, 320, '{"ar":{"moq":"1000 كغ لكل نكهة","name":"كاجو بالفلفل والليمون","grade":"منكّه · فلفل وليمون","specs":[{"label":"الحبة الأساسية","value":"W320"},{"label":"التتبيلة","value":"فلفل حار، أوراق ليمون الكفير، ملح البحر"},{"label":"المذاق","value":"حار ومالح بنكهة الليمون الطازج"},{"label":"مدة الصلاحية","value":"12 شهرًا"},{"label":"العلامة الخاصة","value":"متاحة"}],"origin":"محمّص في فيتنام","summary":"كلاسيكية جنوب شرق آسيا: حرارة الفلفل وعطر أوراق الليمون على كاجو محمّص مقرمش.","packaging":"أكياس مفرّغة أو علب صفيح أو أكياس تجزئة بعلامة خاصة (30–500 غ)","description":"تُحمَّص حبات W320 وتُقلَّب في تتبيلة (فلفل حار، أوراق ليمون الكفير، ملح البحر)، ثم تُبرَّد وتُعبّأ للحفاظ على الطبقة. متوفرة بالجملة أو في أكياس تجزئة بعلامتك الخاصة؛ وتُحمَّص أوراق الليمون المقطّعة مع المكسرات لرائحة منعشة."},"ru":{"moq":"1 000 кг на вкус","name":"Кешью «Чили и лайм»","grade":"С приправой · чили и лайм","specs":[{"label":"Базовое ядро","value":"W320"},{"label":"Приправа","value":"Чили, листья каффир-лайма, морская соль"},{"label":"Вкус","value":"Острый, солёный, свежий лайм"},{"label":"Срок годности","value":"12 месяцев"},{"label":"СТМ","value":"Доступна"}],"origin":"Обжарено во Вьетнаме","summary":"Классика Юго-Восточной Азии: острый чили и ароматный лист лайма на хрустящем обжаренном кешью.","packaging":"Вакуумные пакеты, жестяные банки или розничные пакеты под СТМ (30–500 г)","description":"Ядра W320 обжаривают и обваливают в приправе (чили, листья каффир-лайма, морская соль), затем охлаждают и упаковывают, сохраняя покрытие. Поставляется навалом или в розничных пакетах под вашей маркой; нарезанные листья лайма обжариваются вместе с орехами для свежего аромата."}}', 1, '', '', '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.381Z');
insert into products (id, slug, name, category, grade, summary, description, image, gallery, origin, specs, packaging, moq, featured, published, sort_order, translations, is_sample, seo_title, seo_description, created_at, updated_at) values ('163aa464-8c64-43d4-8e41-51953e444a30', 'honey-roasted-cashews', 'Honey Roasted Cashews', 'cashew', 'Flavoured · honey', 'Golden honey-glazed cashews — one of the most popular flavoured nuts in the US and Korea.', 'W320 kernels are roasted and tumbled in natural honey, a pinch of salt, then cooled and packed to lock in the coating. Available in bulk or in retail pouches with your own label; a light touch of salt keeps the sweetness in balance.', 'https://images.unsplash.com/photo-1723466998040-78d7e2ef6d72', '["https://images.unsplash.com/photo-1729796350013-ebb27f079c76","https://images.unsplash.com/photo-1509912760195-4f6cfd8cce2c"]', 'Roasted in Vietnam', '[{"label":"Base kernel","value":"W320"},{"label":"Seasoning","value":"Natural honey, a pinch of salt"},{"label":"Taste","value":"Sweet and balanced"},{"label":"Shelf life","value":"12 months"},{"label":"Private label","value":"Available"}]', 'Vacuum bags, tins or private-label retail pouches (30–500 g)', '1,000 kg per flavour', 0, 1, 330, '{"ar":{"moq":"1000 كغ لكل نكهة","name":"كاجو محمّص بالعسل","grade":"منكّه · عسل","specs":[{"label":"الحبة الأساسية","value":"W320"},{"label":"التتبيلة","value":"عسل طبيعي، رشة ملح"},{"label":"المذاق","value":"حلو ومتوازن"},{"label":"مدة الصلاحية","value":"12 شهرًا"},{"label":"العلامة الخاصة","value":"متاحة"}],"origin":"محمّص في فيتنام","summary":"كاجو ذهبي مزجّج بالعسل — من أكثر المكسرات المنكّهة شعبية في الولايات المتحدة وكوريا.","packaging":"أكياس مفرّغة أو علب صفيح أو أكياس تجزئة بعلامة خاصة (30–500 غ)","description":"تُحمَّص حبات W320 وتُقلَّب في تتبيلة (عسل طبيعي، رشة ملح)، ثم تُبرَّد وتُعبّأ للحفاظ على الطبقة. متوفرة بالجملة أو في أكياس تجزئة بعلامتك الخاصة؛ ولمسة خفيفة من الملح توازن الحلاوة."},"ru":{"moq":"1 000 кг на вкус","name":"Кешью, обжаренный с мёдом","grade":"С приправой · мёд","specs":[{"label":"Базовое ядро","value":"W320"},{"label":"Приправа","value":"Натуральный мёд, щепотка соли"},{"label":"Вкус","value":"Сладкий и сбалансированный"},{"label":"Срок годности","value":"12 месяцев"},{"label":"СТМ","value":"Доступна"}],"origin":"Обжарено во Вьетнаме","summary":"Золотистый кешью в медовой глазури — один из самых популярных вкусов в США и Корее.","packaging":"Вакуумные пакеты, жестяные банки или розничные пакеты под СТМ (30–500 г)","description":"Ядра W320 обжаривают и обваливают в приправе (натуральный мёд, щепотка соли), затем охлаждают и упаковывают, сохраняя покрытие. Поставляется навалом или в розничных пакетах под вашей маркой; лёгкая нотка соли уравновешивает сладость."}}', 1, '', '', '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.381Z');
insert into products (id, slug, name, category, grade, summary, description, image, gallery, origin, specs, packaging, moq, featured, published, sort_order, translations, is_sample, seo_title, seo_description, created_at, updated_at) values ('d507aed6-d92e-46c9-96f5-9ba250240dc1', 'tomyum-cashews', 'Tom Yum Cashews', 'cashew', 'Flavoured · tom yum', 'Hot-and-sour Thai flavours on roasted cashews, loved across Southeast Asia, Korea and Taiwan.', 'W320 kernels are roasted and tumbled in lemongrass, kaffir lime leaf, chili, tamarind, sea salt, then cooled and packed to lock in the coating. Available in bulk or in retail pouches with your own label; tamarind adds a gentle sourness that sets it apart.', 'https://images.unsplash.com/photo-1729796350013-ebb27f079c76', '["https://images.unsplash.com/photo-1509912760195-4f6cfd8cce2c","https://images.unsplash.com/photo-1729514256038-c489695f4d79"]', 'Roasted in Vietnam', '[{"label":"Base kernel","value":"W320"},{"label":"Seasoning","value":"Lemongrass, kaffir lime leaf, chili, tamarind, sea salt"},{"label":"Taste","value":"Sour, spicy, fragrant lemongrass"},{"label":"Shelf life","value":"12 months"},{"label":"Private label","value":"Available"}]', 'Vacuum bags, tins or private-label retail pouches (30–500 g)', '1,000 kg per flavour', 0, 1, 340, '{"ar":{"moq":"1000 كغ لكل نكهة","name":"كاجو بنكهة توم يام","grade":"منكّه · توم يام","specs":[{"label":"الحبة الأساسية","value":"W320"},{"label":"التتبيلة","value":"عشبة الليمون، أوراق ليمون الكفير، فلفل حار، تمر هندي، ملح البحر"},{"label":"المذاق","value":"حامض وحار بعطر عشبة الليمون"},{"label":"مدة الصلاحية","value":"12 شهرًا"},{"label":"العلامة الخاصة","value":"متاحة"}],"origin":"محمّص في فيتنام","summary":"نكهات تايلاندية حامضة وحارة على كاجو محمّص، محبوبة في جنوب شرق آسيا وكوريا وتايوان.","packaging":"أكياس مفرّغة أو علب صفيح أو أكياس تجزئة بعلامة خاصة (30–500 غ)","description":"تُحمَّص حبات W320 وتُقلَّب في تتبيلة (عشبة الليمون، أوراق ليمون الكفير، فلفل حار، تمر هندي، ملح البحر)، ثم تُبرَّد وتُعبّأ للحفاظ على الطبقة. متوفرة بالجملة أو في أكياس تجزئة بعلامتك الخاصة؛ ويضيف التمر الهندي حموضة لطيفة تميّزها."},"ru":{"moq":"1 000 кг на вкус","name":"Кешью «Том ям»","grade":"С приправой · том ям","specs":[{"label":"Базовое ядро","value":"W320"},{"label":"Приправа","value":"Лемонграсс, лист каффир-лайма, чили, тамаринд, морская соль"},{"label":"Вкус","value":"Кисло-острый, с ароматом лемонграсса"},{"label":"Срок годности","value":"12 месяцев"},{"label":"СТМ","value":"Доступна"}],"origin":"Обжарено во Вьетнаме","summary":"Кисло-острые тайские вкусы на обжаренном кешью — популярны в Юго-Восточной Азии, Корее и на Тайване.","packaging":"Вакуумные пакеты, жестяные банки или розничные пакеты под СТМ (30–500 г)","description":"Ядра W320 обжаривают и обваливают в приправе (лемонграсс, лист каффир-лайма, чили, тамаринд, морская соль), затем охлаждают и упаковывают, сохраняя покрытие. Поставляется навалом или в розничных пакетах под вашей маркой; тамаринд добавляет мягкую кислинку, которая выделяет этот вкус."}}', 1, '', '', '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.381Z');

