insert into testimonials (id, quote, name, role, company, country, flag, product_slug, since, rating, image, logo, translations, is_sample, published, sort_order, created_at, updated_at) values ('68e8a8c4-b0c5-43d7-be04-b2711e10f899', 'Clear specs, quick documents and honest updates when vessels were delayed. Switching our WW320 supply to Cao Gia was easy.', 'Marcus Reid', 'Procurement Manager', 'Mirabel Foods', 'United States', '🇺🇸', 'cashew-ww320', 2022, 5, 'https://images.unsplash.com/photo-1723466998040-78d7e2ef6d72', NULL, '{"ar":{"role":"مدير المشتريات","quote":"مواصفات واضحة ومستندات سريعة وتحديثات صادقة عند تأخر السفن. كان نقل توريد WW320 إلى كاو جيا أمرًا سهلًا.","country":"الولايات المتحدة"},"ru":{"role":"Менеджер по закупкам","quote":"Понятные спецификации, быстрые документы и честная информация о задержках судов. Перевести закупки WW320 на Cao Gia было просто.","country":"США"}}', 1, 0, 20, '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.398Z');
insert into testimonials (id, quote, name, role, company, country, flag, product_slug, since, rating, image, logo, translations, is_sample, published, sort_order, created_at, updated_at) values ('ec019316-9a93-4cab-afb8-e28fc91f7b10', 'Their Cau Dat Arabica surprised our customers. The team helped us plan a forward contract for the whole season.', 'Aiko Tanaka', 'Founder', 'Sable Street Coffee', 'Japan', '🇯🇵', 'arabica-s18-clean', 2020, 5, 'https://images.unsplash.com/photo-1750967613671-297f1b63038d', NULL, '{"ar":{"role":"المؤسسة","quote":"فاجأت أرابيكا كاو دات عملاءنا. وساعدنا الفريق في التخطيط لعقد آجل يغطي الموسم كاملًا.","country":"اليابان"},"ru":{"role":"Основатель","quote":"Арабика из Каудат удивила наших клиентов. Команда помогла спланировать форвардный контракт на весь сезон.","country":"Япония"}}', 1, 0, 30, '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.398Z');
insert into testimonials (id, quote, name, role, company, country, flag, product_slug, since, rating, image, logo, translations, is_sample, published, sort_order, created_at, updated_at) values ('653bb91f-a1b6-4c40-92c2-12d473e8ce59', 'Private-label roasted coffee delivered on schedule with our branding. The samples process was fast and professional.', 'Omar Haddad', 'Category Buyer', 'Lumen Nut Co.', 'United Arab Emirates', '🇦🇪', NULL, 2023, 5, 'https://images.unsplash.com/photo-1447933601403-0c6688de566e', NULL, '{"ar":{"role":"مسؤول مشتريات الفئة","quote":"وصلت القهوة المحمّصة بعلامتنا الخاصة في موعدها. وكانت إجراءات العيّنات سريعة واحترافية.","country":"الإمارات العربية المتحدة"},"ru":{"role":"Категорийный менеджер","quote":"Обжаренный кофе под нашей маркой пришёл точно в срок. Работа с образцами — быстрая и профессиональная.","country":"ОАЭ"}}', 1, 0, 40, '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.398Z');

