insert into team_members (id, name, role, bio, quote, photo, email, whatsapp, is_ceo, translations, is_sample, published, sort_order, created_at, updated_at) values ('8b7d8dcd-db5a-4ccd-98ba-73260dee20bd', 'Cao Đức', 'CEO', '["Mr. Cao Đức leads Cao Gia, which has exported Vietnamese green coffee and cashew kernels since 2018.","Under his direction the company ships 10–30 containers a year from its warehouses in Dak Lak and northern Vietnam to buyers in the United States, the European Union, Russia, the Middle East, Japan, South Korea and Australia."]', '', NULL, 'caogiaxk2022@gmail.com', '+84 867 282 139', 1, '{"ar":{"bio":["يقود السيد كاو دوك شركة كاو جيا التي تصدّر البن الأخضر وحبات الكاجو الفيتنامية منذ عام 2018.","وتحت إدارته تشحن الشركة من 10 إلى 30 حاوية سنويًا من مستودعاتها في داك لاك وشمال فيتنام إلى مشترين في الولايات المتحدة والاتحاد الأوروبي وروسيا والشرق الأوسط واليابان وكوريا الجنوبية وأستراليا."],"role":"الرئيس التنفيذي","quote":""},"ru":{"bio":["Г-н Као Дык руководит компанией Cao Gia, которая с 2018 года экспортирует вьетнамский зелёный кофе и ядра кешью.","Под его руководством компания отгружает 10–30 контейнеров в год со своих складов в Даклаке и на севере Вьетнама покупателям в США, Европейском союзе, России, на Ближнем Востоке, в Японии, Южной Корее и Австралии."],"role":"Генеральный директор","quote":""}}', 0, 1, 10, '2026-10-21T23:01:24.381Z', '2026-10-21T23:01:24.404Z');
